data atrading; set midas.security;
if 2012 le year(date) le 2018;
keep ticker security date qtr oddlotvol cancels littrades litvol tradesforoddlots trade_to_order_volume cancel_to_trade OrderVol;

data firm_char;
    set comp.funda;
    where indfmt="INDL" and datafmt="STD" and consol="C" and curcd="USD";
    if 2011 < fyear < 2022 ;
	keep gvkey tic fyear datadate sich cik at prcc_f;

data stocknames; set crsp.stocknames;
keep permno ticker comnam namedt nameenddt exchcd;
rename ticker=crsptic;
run;

/* import the forward-looking data */
data fl_MDA;set mydata.fl_MDA;
run;

proc sql;
create table atrading4 as
select a.*, b.*
from atrading3 as a left join fl_MDA as b
on a.gvkey=b.char_gvkey and a.fyear=b.fyear;
quit;

data atrading4;set atrading4;
if missing(difference) then delete;
run;

proc summary data=atrading;
by ticker;
class year;
var OLR ATS TOR CTR OLRlog ATSlog TORlog CTRlog;
output out=atrading1 (drop= _type_ _freq_) mean= ;
run;

data atrading2; set atrading1;
if missing(year) then delete;
if exchcd ne 1 and exchcd ne 2; /*exclude stocks from NYSE and AMEX due to data comparability issues with other exchanges*/
run;

/* get standard deviation of monthly stock returns */
data return; set crsp.msf;
keep permno date ret;
run;

data return;set return;
Year=year(date);
if 2010 le Year le 2020;
run;

/* get institutional ownership */
proc sort data=tfn.s34 (keep= rdate cusip ticker shrout1 shrout2 prc shares mgrno)
out=temp1; 
where  ("01jan&2011"d <= rdate <= "31dec&2019"d ) ;
by cusip rdate;
run;

/* get BigN variable */
data auditor;set audit.auditopin;
if 2010 < fiscal_year_of_op < 2020;
keep auditor_name company_fkey fiscal_year_end_op fiscal_year_of_op;
run;

data sales;set comp.funda;
if 2010 < fyear < 2021;
keep gvkey fyear revt sich;
if missing(sich) then delete;
if missing(revt) then delete;
run;

proc sql;
create table sales1 as
select gvkey, fyear, sich, revt, sum(revt) as sum_revt
from sales
group by fyear,sich;
quit;

data sales1;set sales1;
market_share_sqr = (revt/sum_revt)**2;
run;

proc rank data=sales1 out=ranked(where=(firm_rank<=100)) descending;
by fyear sich;
var market_share_sqr;
ranks firm_rank;
run;

proc means nway missing noprint data=ranked;
class fyear sich;
var market_share_sqr;
output out=herfin (drop=_type_ _freq_) sum=;
run;

proc sql;
create table atrading10
as select a.*, b.market_share_sqr
from atrading9 a left join herfin b
on a.sich=b.sich and a.fyear=b.fyear;
quit;

/* get changes in trading volume*/
data crsp_d; set crsp.dsf;
keep date permno vol prc shrout cfacshr;
if 2010 < year(date) < 2022;
run;

/*get number of 8Ks*/;
proc sort data=mydata.IndexLinks_8k out=IndexLinks_8k ;
by cik filingdate;
run;

proc sort data=IndexLinks_8k out=IndexLinks_8k;
by cik;
run;

data mydata.finaldataMDAAT;
set  mydata.finaldataMDAAT;
previousdate=INTNX('DAY', fillingdate, -364);
format previousdate MMDDYY10.;
run;

proc sql;
  create table mydata.finaldataMDAAT as 
  select *, 
    count(b.filingdate) as n_8k, b.cik as cikbb
  from mydata.finaldataMDAAT as a   
  left join IndexLinks_8k as b 
    on (a.cikd = b.cik and
        a.previousdate le b.filingdate le a.fillingdate)
  group by a.cik, a.fillingdate
  order by a.cik, a.fillingdate;
quit;

proc sort data=mydata.finaldataMDAAT out=mydata.finaldataMDAAT nodupkey;
by cik fillingdate;
run;

/*final data modify*/;
data mydata.finaldataMDAAT;set mydata.finaldataMDAAT;
Where nmiss ( AT,OLRlog,TORlog,CTRlog,ATSlog,difference,Size,dolvol_change,EPS_change,Current_change,Debtdue_change,Leverage_change, 
FCF_change,Downsize,Acquire,std_ret_change,instit_pct,Litigation,Big6,Herfindahl,n_8k)=0;

data mydata.finaldataMDAAT;set atrading10;
if missing(sich) then delete;
if missing(std_ret_change) then delete;
EPS_change=abs(EPS_change);
Current_change=abs(Current_change);
Debtdue_change=abs(Debtdue_change);
Leverage_change=abs(Leverage_change);
FCF_change=abs(FCF_change);
std_ret_change=abs(std_ret_change);
Herfindahl=market_share_sqr;
drop market_share_sqr;
run;
